-- Generated by scripts/gen_m365_usage_sql.py - edit the generator, not this file.
-- Runs on the Lakehouse SQL endpoint from the M365 Usage Analytics template (m365_usage_sessionstats).
-- Copilot sessions and prompts per user, day and app (the PAX Session Stats file).
WITH
cp AS (
    SELECT
        MIN(COALESCE(Audit_UserId, '')) AS c_uid,
        CONCAT(MIN(CAST(InteractionDate AS VARCHAR(10))), 'T00:00:00.000Z') AS c_dk,
        CONCAT(CONVERT(VARCHAR(23), MIN(CreationDate), 126), 'Z') AS c_tm,
        MIN(COALESCE(Workload, '')) AS c_wl,
        MIN(COALESCE(AppHost, '')) AS c_host,
        MIN(COALESCE(AgentId, '')) AS c_agid,
        MIN(COALESCE(AgentName, '')) AS c_agname,
        MIN(COALESCE(Context_Type, '')) AS c_ctx,
        MIN(COALESCE(ThreadId, '')) AS c_thread,
        CAST(COUNT(DISTINCT CASE WHEN LOWER(CAST(Message_isPrompt AS VARCHAR(10))) IN ('true', '1')
                                 THEN Message_Id END) AS BIGINT) AS c_pc,
        CAST(MAX(COALESCE(Resource_Count, 0)) AS BIGINT) AS c_rc
    FROM dbo.copilot_interactions_parsed
    WHERE COALESCE(Audit_UserId, '') LIKE '%@%.%'
    GROUP BY Source_RecordKey
),
ix AS (
    SELECT c_uid AS UserId, c_dk AS CreationDate, c_tm AS CreationTime, 'CopilotInteraction' AS Operation,
        c_wl AS Workload, c_host AS AppHost, c_agid AS AgentId, c_agname AS AgentName, c_ctx AS ContextType,
        c_thread AS ThreadId, c_pc AS PromptCount, c_pc AS ResponseCount,
        CASE WHEN c_pc >= 1000 OR c_rc >= 1000 THEN 1000
             WHEN c_pc >= c_rc AND c_pc >= 1 THEN c_pc
             WHEN c_rc >= 1 THEN c_rc
             ELSE 1 END AS EventCount,
        CASE WHEN c_agid <> '' OR LOWER(c_host) IN ('agent', 'copilotstudio', 'declarativeagent', 'customengineagent') THEN 1 ELSE 0 END AS ag
    FROM cp
    UNION ALL SELECT COALESCE(UserId, '') AS UserId, COALESCE(CreationDate, '') AS CreationDate,
        COALESCE(CreationTime, '') AS CreationTime, 'AIAppInteraction' AS Operation, COALESCE(Workload, '') AS Workload,
        COALESCE(AppHost, '') AS AppHost, COALESCE(AgentId, '') AS AgentId, COALESCE(AgentName, '') AS AgentName,
        COALESCE(ContextType, '') AS ContextType, COALESCE(ThreadId, '') AS ThreadId,
        CAST(COALESCE(PromptCount, 0) AS BIGINT) AS PromptCount, CAST(COALESCE(ResponseCount, 0) AS BIGINT) AS ResponseCount,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS EventCount,
        CASE WHEN UPPER(COALESCE(IsAgent, '')) = 'TRUE' THEN 1 ELSE 0 END AS ag
    FROM dbo.connected_ai_app_interactions
    UNION ALL SELECT COALESCE(UserId, '') AS UserId, COALESCE(CreationDate, '') AS CreationDate,
        COALESCE(CreationTime, '') AS CreationTime, 'AIAppInteraction' AS Operation, COALESCE(Workload, '') AS Workload,
        COALESCE(AppHost, '') AS AppHost, COALESCE(AgentId, '') AS AgentId, COALESCE(AgentName, '') AS AgentName,
        COALESCE(ContextType, '') AS ContextType, COALESCE(ThreadId, '') AS ThreadId,
        CAST(COALESCE(PromptCount, 0) AS BIGINT) AS PromptCount, CAST(COALESCE(ResponseCount, 0) AS BIGINT) AS ResponseCount,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS EventCount,
        CASE WHEN UPPER(COALESCE(IsAgent, '')) = 'TRUE' THEN 1 ELSE 0 END AS ag
    FROM dbo.ai_app_interactions
),
-- The PAX Rollup file: non-AI operations from the lake rollup plus AI interactions rolled up to the same grain.
ru AS (
    SELECT UserId, CreationDate, Operation, Workload, SourceFileExtension, AppHost,
        CAST(COALESCE(EventCount, 1) AS BIGINT) AS EventCount, CAST(COALESCE(ItemsAccessedCount, 0) AS BIGINT) AS ItemsAccessedCount,
        CreationTime, MaxCreationTime, AgentId, AgentName, ContextType, IsAgentInteraction
    FROM dbo.m365_usage_rollup
    WHERE COALESCE(Operation, '') NOT IN ('CopilotInteraction', 'AIAppInteraction', 'ConnectedAIAppInteraction')
    UNION ALL
    SELECT MIN(UserId), CreationDate, Operation, Workload, '', AppHost,
        SUM(EventCount), CAST(0 AS BIGINT),
        COALESCE(MIN(CASE WHEN CreationTime <> '' THEN CreationTime END), ''),
        COALESCE(MAX(CASE WHEN CreationTime <> '' THEN CreationTime END), ''),
        AgentId, AgentName, ContextType,
        CASE WHEN MAX(ag) = 1 THEN 'TRUE' ELSE 'FALSE' END
    FROM ix
    GROUP BY LOWER(UserId), CreationDate, Operation, Workload, AppHost, AgentId, AgentName, ContextType
),
s AS (
    SELECT MIN(UserId) AS UserId, CreationDate, AppHost,
        COUNT(DISTINCT CASE WHEN ThreadId <> '' AND PromptCount > 0 THEN ThreadId END) AS SessionCount,
        SUM(PromptCount) AS PromptCount,
        SUM(CASE WHEN ag = 1 THEN PromptCount ELSE 0 END) AS AgentPromptCount,
        SUM(ResponseCount) AS ResponseCount,
        COUNT(DISTINCT CASE WHEN ThreadId <> '' AND PromptCount > 0 AND ag = 1 THEN ThreadId END) AS AgentSessionCount
    FROM ix
    GROUP BY LOWER(UserId), CreationDate, AppHost
)
SELECT UserId, CreationDate, AppHost, SessionCount, PromptCount, AgentPromptCount, ResponseCount, AgentSessionCount
FROM s
WHERE NOT (SessionCount = 0 AND PromptCount = 0)
